/** Which sessions to show before "Show all": one past session, the current one, and the next few. */
export function seriesWindow<T extends { event_id: string }>(rows: T[], currentId: string, limit = 5): T[] {
  if (rows.length <= limit) return rows;
  const idx = rows.findIndex((r) => r.event_id === currentId);
  if (idx < 0) return rows.slice(0, limit);
  const start = Math.max(0, idx - 1);
  const end = Math.min(rows.length, start + limit);
  const back = Math.max(0, end - limit);
  return rows.slice(back, end);
}

/** "Week N of M", or just the count when this event is not in the list. */
export function seriesWeekLabel(index: number, total: number): string {
  if (total <= 0) return '';
  if (index >= 0) return `Week ${index + 1} of ${total}`;
  return total === 1 ? '1 session' : `${total} sessions`;
}

/** Hide a session title that only repeats the series name. */
export function seriesSessionTitle(title: string | null | undefined, seriesTitle: string | null | undefined): string | null {
  const t = title?.trim() ?? '';
  if (!t) return null;
  const s = seriesTitle?.trim() ?? '';
  if (s && t.toLowerCase() === s.toLowerCase()) return null;
  return t;
}
