// Sibling sessions for a Meetup series, on the club event page.
import React, { useEffect, useState } from 'react';
import { Text, View } from 'react-native';
import { router } from 'expo-router';
import { Button, ListRow, StatusPill, styles } from './ui';
import { listEventSeries, type EventSeriesSession } from '../lib/api';
import { eventEnded, fmtTime } from '../lib/format';
import { seriesSessionTitle, seriesWeekLabel, seriesWindow } from '../lib/series';
import { fs } from '../lib/theme';

const NEARBY = 5;

function when(iso: string): string {
  const d = new Date(iso);
  const date = d.toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' });
  return `${date} · ${fmtTime(iso)}`;
}

export function EventSeries({ eventId, fallbackTitle }: { eventId: string; fallbackTitle: string }) {
  const [rows, setRows] = useState<EventSeriesSession[] | null>(null);
  const [all, setAll] = useState(false);
  useEffect(() => {
    let live = true;
    setAll(false);
    setRows(null);
    listEventSeries(eventId).then((r) => { if (live) setRows(r); }).catch(() => { if (live) setRows([]); });
    return () => { live = false; };
  }, [eventId]);

  if (!rows || rows.length < 2) return null;
  const index = rows.findIndex((r) => r.event_id === eventId);
  const name = rows[0]?.series_title?.trim() || fallbackTitle;
  const shown = all ? rows : seriesWindow(rows, eventId, NEARBY);
  const week = seriesWeekLabel(index, rows.length);
  return (
    <View style={styles.listCard}>
      <View style={styles.listTitle}>
        <Text style={styles.sectionTitle}>Series</Text>
        <Text style={[styles.muted, { flex: 1, fontSize: fs(13) }]} numberOfLines={1}>{name}</Text>
        {week ? <Text style={[styles.muted, { fontSize: fs(12) }]}>{week}</Text> : null}
      </View>
      {shown.map((r) => {
        const current = r.event_id === eventId;
        const title = seriesSessionTitle(r.title, name);
        const going = r.going == null ? null : `${r.going} going`;
        const open = !current && !!r.event_id;
        return (
          <ListRow key={r.event_id} dim={!current && eventEnded(r)} onPress={open ? () => router.push(`/events/${r.event_id}`) : undefined}
            accessibilityLabel={`${current ? 'This event, ' : ''}${when(r.starts_at)}${title ? `, ${title}` : ''}${going ? `, ${going}` : ''}`}>
            <View style={{ flex: 1, minWidth: 0, gap: 2 }}>
              <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, minWidth: 0 }}>
                <Text style={[styles.rowPrimary, { flex: 1 }]} numberOfLines={1}>{when(r.starts_at)}</Text>
                {going ? <Text style={styles.rowCell}>{going}</Text> : null}
                {current ? <StatusPill label="This event" tone="info" /> : null}
              </View>
              {title ? <Text style={[styles.muted, { fontSize: fs(12) }]} numberOfLines={1}>{title}</Text> : null}
            </View>
          </ListRow>
        );
      })}
      {rows.length > NEARBY ? (
        <View style={{ paddingHorizontal: 16, paddingVertical: 12 }}>
          <Button small variant="neutral" title={all ? 'Show nearby' : `Show all (${rows.length})`} onPress={() => setAll((v) => !v)} />
        </View>
      ) : null}
    </View>
  );
}
