// Create a private chat for this event, or change which events an existing one is linked to.
import React, { useEffect, useMemo, useState } from 'react';
import { Modal, Pressable, ScrollView, Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { Avatar, Button, ErrorText, Field, styles } from './ui';
import {
  createEventChat,
  eventChatInvitePresets,
  eventChatLinkTargets,
  getProfiles,
  listRoomEventLinks,
  roomAttachedSeries,
  searchProfiles,
  setEventChatEvents,
} from '../lib/api';
import {
  INVITE_PRESETS,
  checkedEventIds,
  eventLinkDelta,
  pinMember,
  selectedMemberIds,
  type EventChatLink,
  type EventChatTarget,
  type InvitePreset,
} from '../lib/event-chats';
import { primaryName, handle } from '../lib/names';
import { colors, fonts, fs } from '../lib/theme';
import type { Profile } from '../lib/types';

function when(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleDateString([], { month: 'short', day: 'numeric' });
}

function CheckRow({ checked, disabled, label, detail, onPress }: {
  checked: boolean;
  disabled?: boolean;
  label: string;
  detail?: string | null;
  onPress: () => void;
}) {
  return (
    <Pressable onPress={onPress} disabled={disabled} accessibilityRole="checkbox"
      accessibilityState={{ checked, disabled: !!disabled }} accessibilityLabel={label}>
      <View style={{ flexDirection: 'row', alignItems: 'flex-start', gap: 10, opacity: disabled ? 0.7 : 1, paddingVertical: 6 }}>
        <Ionicons name={checked ? 'checkbox' : 'square-outline'} size={20} color={colors.navy} style={{ marginTop: 1 }} />
        <View style={{ flex: 1, minWidth: 0 }}>
          <Text style={styles.body}>{label}</Text>
          {detail ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{detail}</Text> : null}
        </View>
      </View>
    </Pressable>
  );
}

export function EventChatSheet({ visible, mode, anchorId, anchorTitle, roomId, onClose, onSaved }: {
  visible: boolean;
  mode: 'create' | 'edit';
  anchorId: string;
  anchorTitle: string;
  roomId?: string;
  onClose: () => void;
  onSaved: (roomId: string) => void;
}) {
  const [title, setTitle] = useState('');
  const [targets, setTargets] = useState<EventChatTarget[]>([]);
  const [links, setLinks] = useState<EventChatLink[]>([]);
  const [presetIds, setPresetIds] = useState<Record<InvitePreset, string[]>>({ rsvp: [], attending: [], hosting: [] });
  const [active, setActive] = useState<Set<InvitePreset>>(new Set());
  const [pinned, setPinned] = useState<Set<string>>(new Set());
  const [excluded, setExcluded] = useState<Set<string>>(new Set());
  const [manual, setManual] = useState<Set<string>>(new Set());
  const [attach, setAttach] = useState(false);
  const [hadSeries, setHadSeries] = useState(false);
  const [people, setPeople] = useState<Record<string, Profile>>({});
  const [search, setSearch] = useState('');
  const [hits, setHits] = useState<Profile[]>([]);
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    if (!visible) return;
    let live = true;
    setTitle(`${anchorTitle} chat`.slice(0, 120));
    setActive(new Set());
    setPinned(new Set());
    setExcluded(new Set());
    setManual(new Set());
    setAttach(false);
    setHadSeries(false);
    setSearch('');
    setHits([]);
    setErr(null);
    setReady(false);
    (async () => {
      const [presetRows, targetRows, linkRows, seriesIds] = await Promise.all([
        mode === 'create' ? eventChatInvitePresets(anchorId) : Promise.resolve([]),
        eventChatLinkTargets(anchorId),
        mode === 'edit' && roomId ? listRoomEventLinks(roomId) : Promise.resolve([]),
        mode === 'edit' && roomId ? roomAttachedSeries(roomId) : Promise.resolve([]),
      ]);
      if (!live) return;
      const grouped: Record<InvitePreset, string[]> = { rsvp: [], attending: [], hosting: [] };
      for (const row of presetRows) {
        if (!grouped[row.preset].includes(row.user_id)) grouped[row.preset].push(row.user_id);
      }
      const anchor = targetRows.find((row) => row.event_id === anchorId);
      const seriesOn = !!anchor?.series_id && seriesIds.includes(anchor.series_id);
      setPresetIds(grouped);
      setTargets(targetRows);
      setLinks(linkRows);
      setManual(new Set(linkRows.filter((row) => row.source === 'manual').map((row) => row.event_id)));
      setAttach(seriesOn);
      setHadSeries(seriesOn);
      setReady(true);
      const ids = presetRows.map((row) => row.user_id);
      if (ids.length) {
        const profiles = await getProfiles(ids);
        if (live) setPeople((cur) => ({ ...cur, ...profiles }));
      }
    })().catch((e: { message?: string }) => {
      if (live) setErr(e.message ?? 'Couldn’t load this chat.');
    });
    return () => { live = false; };
  }, [visible, mode, anchorId, anchorTitle, roomId]);

  useEffect(() => {
    if (!visible || mode !== 'create') return;
    let live = true;
    const q = search.trim();
    if (q.length < 2) {
      setHits([]);
      return;
    }
    searchProfiles(q).then((rows) => {
      if (!live) return;
      setHits(rows);
      setPeople((cur) => {
        const next = { ...cur };
        for (const row of rows) next[row.id] = row;
        return next;
      });
    }).catch(() => { if (live) setHits([]); });
    return () => { live = false; };
  }, [search, visible, mode]);

  const anchor = targets.find((row) => row.event_id === anchorId);
  const seriesId = anchor?.series_id ?? null;
  const seriesTitle = anchor?.series_title?.trim() || 'this series';
  const seriesCount = seriesId ? targets.filter((row) => row.series_id === seriesId).length : 0;
  const checked = useMemo(() => checkedEventIds({
    anchorId,
    lockAnchor: mode === 'create',
    manual,
    attachSeries: attach,
    seriesId,
    targets,
  }), [anchorId, mode, manual, attach, seriesId, targets]);
  const selected = useMemo(() => selectedMemberIds({
    presets: presetIds,
    active,
    pinned,
    excluded,
  }), [presetIds, active, pinned, excluded]);

  const shownPeople = useMemo(() => {
    const ids = new Set<string>([...selected, ...hits.map((hit) => hit.id)]);
    return [...ids];
  }, [selected, hits]);

  const togglePerson = (id: string, on: boolean) => {
    const next = pinMember(pinned, excluded, id, on);
    setPinned(next.pinned);
    setExcluded(next.excluded);
  };

  const toggleEvent = (id: string) => {
    if (mode === 'create' && id === anchorId) return;
    if (attach && seriesId && targets.find((row) => row.event_id === id)?.series_id === seriesId) return;
    setManual((cur) => {
      const next = new Set(cur);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const save = async () => {
    if (busy) return;
    setBusy(true);
    setErr(null);
    try {
      if (mode === 'create') {
        const also = [...manual].filter((id) => id !== anchorId);
        const id = await createEventChat({
          eventId: anchorId,
          title: title.trim(),
          memberIds: selected,
          alsoEventIds: also,
          attachSeries: attach,
        });
        onSaved(id);
      } else if (roomId) {
        const delta = eventLinkDelta({
          links,
          selected: [...checked],
          detachSeries: hadSeries && !attach,
        });
        await setEventChatEvents({
          roomId,
          add: delta.add,
          remove: delta.remove,
          attachSeries: attach && !hadSeries,
          detachSeries: hadSeries && !attach,
          anchorEventId: anchorId,
        });
        onSaved(roomId);
      }
    } catch (e: any) {
      setErr(e.message ?? 'Couldn’t save the chat.');
    } finally {
      setBusy(false);
    }
  };

  const dismiss = () => { if (!busy) onClose(); };
  return (
    <Modal transparent visible={visible} animationType="fade" onRequestClose={dismiss}>
      <Pressable style={{ flex: 1, backgroundColor: 'rgba(18,41,75,.35)', justifyContent: 'flex-end' }} onPress={dismiss}>
        <Pressable testID="event-chat-sheet" style={{ backgroundColor: colors.paper, borderTopLeftRadius: 18, borderTopRightRadius: 18, maxWidth: 640, width: '100%', alignSelf: 'center', maxHeight: '88%' }}>
          <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{ padding: 20, gap: 12 }}>
            <Text style={styles.h2}>{mode === 'create' ? 'New chat' : 'Events for this chat'}</Text>
            <Text style={styles.body}>
              {mode === 'create'
                ? 'Only the people you add can see this chat. Everyone else who can see the event cannot.'
                : 'People already in the chat stay. This changes which events it is linked to.'}
            </Text>
            {mode === 'create' ? (
              <Field label="Name" value={title} onChangeText={setTitle} maxLength={120} />
            ) : null}
            {mode === 'create' ? (
              <View>
                <Text style={styles.label}>Add people</Text>
                {INVITE_PRESETS.map((preset) => (
                  <CheckRow key={preset.id} checked={active.has(preset.id)}
                    label={`${preset.label}${presetIds[preset.id].length ? ` (${presetIds[preset.id].length})` : ''}`}
                    detail={preset.detail}
                    onPress={() => setActive((cur) => {
                      const next = new Set(cur);
                      if (next.has(preset.id)) next.delete(preset.id);
                      else next.add(preset.id);
                      return next;
                    })} />
                ))}
                <Text style={[styles.muted, { fontSize: fs(12), marginTop: 4 }]}>Presets include members with an app account. Meetup guests without one are left out.</Text>
                <Field label="Search members" value={search} onChangeText={setSearch} placeholder="Name or username" autoCapitalize="none" />
                {shownPeople.map((id) => {
                  const profile = people[id] ?? hits.find((hit) => hit.id === id);
                  const name = profile ? primaryName(profile) : 'Member';
                  return (
                    <Pressable key={id} onPress={() => togglePerson(id, !selected.includes(id))} accessibilityRole="checkbox"
                      accessibilityState={{ checked: selected.includes(id) }} accessibilityLabel={name}>
                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, paddingVertical: 6 }}>
                        <Ionicons name={selected.includes(id) ? 'checkbox' : 'square-outline'} size={20} color={colors.navy} />
                        <Avatar name={name} path={profile?.avatar_path} userId={id} size={28} />
                        <View style={{ flex: 1, minWidth: 0 }}>
                          <Text style={styles.rowPrimary} numberOfLines={1}>{name}</Text>
                          {profile?.username ? <Text style={[styles.muted, { fontSize: fs(12) }]} numberOfLines={1}>{handle(profile)}</Text> : null}
                        </View>
                      </View>
                    </Pressable>
                  );
                })}
                {selected.length === 0 && search.trim().length < 2 ? (
                  <Text style={[styles.muted, { fontSize: fs(13) }]}>You are included. Add other members if you want.</Text>
                ) : null}
              </View>
            ) : null}
            <View>
              <Text style={styles.label}>Events</Text>
              {seriesId ? (
                <CheckRow checked={attach} label="Attach the whole series" disabled={!ready || busy}
                  detail={seriesCount > 1
                    ? `Links the ${seriesCount} sessions in ${seriesTitle}, including ones you don’t host. Later sessions are added when they sync.`
                    : `Links later sessions in ${seriesTitle} when they sync.`}
                  onPress={() => setAttach((v) => !v)} />
              ) : (
                <Text style={[styles.muted, { fontSize: fs(13), marginBottom: 6 }]}>This event isn’t part of a Meetup series. Pick other events below.</Text>
              )}
              {targets.map((row) => {
                const forced = (mode === 'create' && row.event_id === anchorId) || (!!attach && !!seriesId && row.series_id === seriesId);
                const current = row.event_id === anchorId;
                return (
                  <CheckRow key={row.event_id} checked={checked.has(row.event_id)} disabled={forced || busy}
                    label={`${when(row.starts_at) ? `${when(row.starts_at)} · ` : ''}${row.title}`}
                    detail={current ? 'This event' : row.series_id && row.series_id === seriesId ? 'In this series' : null}
                    onPress={() => toggleEvent(row.event_id)} />
                );
              })}
              {!ready && !err ? <Text style={[styles.muted, { fontSize: fs(13) }]}>Loading events…</Text> : null}
            </View>
            <ErrorText>{err}</ErrorText>
            <View style={{ flexDirection: 'row', gap: 10, justifyContent: 'flex-end' }}>
              <Button title="Cancel" variant="ghost" small disabled={busy} onPress={dismiss} />
              <Button title={mode === 'create' ? 'Create chat' : 'Save'} small loading={busy}
                disabled={mode === 'create' && !title.trim()} onPress={save} />
            </View>
            <Text style={{ fontFamily: fonts.sans, fontSize: fs(12), color: colors.faint }}>
              Only a host can create or change these links.
            </Text>
          </ScrollView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}
