// Event record page (signed-in members). Moderators also get Edit and Publish to.
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, Text, View } from 'react-native';
import { Redirect, router, Stack, useFocusEffect, useLocalSearchParams } from 'expo-router';
import { BackChevron, Button, EmptyState, ErrorText, FieldGrid, Page, SectionCard, StatusPill, styles } from '../../../components/ui';
import { PlaceValue, eventEndMs, isLive } from '../../../components/events';
import { ActionRow, CoverBand, EntityTitle } from '../../../components/record-chrome';
import { PublishToList } from '../../../components/publish-to';
import { EventAttendance } from '../../../components/attendance';
import { EventSeries } from '../../../components/event-series';
import { EventChats } from '../../../components/event-chats';
import { RichText } from '../../../components/rich-text';
import { attendanceClosed, attendanceClosedMessage, fmtDate } from '../../../lib/format';
import { applyToEvent, attendEvent, attendUnlistedEvent, canDeleteEvent, cancelAttend, deleteEvent, eventUnlistedToken, getEvent, myEventApplication, myEventRsvp } from '../../../lib/api';
import { EventApplications } from '../../../components/event-applications';
import { eventVisibility, eventVisibilityLabel, rsvpAction } from '../../../lib/event-visibility';
import { getGroup } from '../../../lib/groups';
import { flash } from '../../../lib/flash';
import { useConfirmDelete } from '../../../components/confirm-sheet';
import { DeleteEventSheet } from '../../../components/delete-event-sheet';
import { rememberReturnPath } from '../../../lib/auth';
import { entitledAddress, entitledWhere, lockedDetailFields, lockedWhere, publicDescription } from '../../../lib/place';
import { trackEventPageView } from '../../../lib/analytics';
import { OwnerFace } from '../../../components/owner-face';
import { useOwnerProfile } from '../../../lib/owner-label';
import { useSession } from '../../../lib/session';
import { colors } from '../../../lib/theme';
import type { ClubEvent, EventApplicationStatus } from '../../../lib/types';

export default function EventPage() {
  const raw = useLocalSearchParams<{ id: string }>().id;
  const id = Array.isArray(raw) ? raw[0] : raw;
  const { userId, isModerator, demo, loading } = useSession();
  const mod = isModerator && !demo && !!userId;
  const [e, setE] = useState<ClubEvent | null | undefined>(undefined);
  const [going, setGoing] = useState(false);
  const [application, setApplication] = useState<EventApplicationStatus | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [canDelete, setCanDelete] = useState(false);
  const removeSheet = useConfirmDelete();
  const [group, setGroup] = useState<{ id: string; name: string } | null>(null);
  const owner = useOwnerProfile(e?.owner_id, mod);
  const load = useCallback(() => {
    if (!userId || !id) return;
    Promise.all([getEvent(id), myEventRsvp(id, userId), myEventApplication(id, userId), canDeleteEvent(id).catch(() => false)]).then(([row, rsvp, status, allowed]) => {
      setE(row); setGoing(rsvp); setApplication(status); setCanDelete(allowed);
    }).catch((x) => setErr(x.message));
  }, [userId, id]);
  useFocusEffect(useCallback(() => { load(); }, [load]));
  useFocusEffect(useCallback(() => {
    const eventId = e?.id;
    if (eventId && eventId === id && userId && !demo) trackEventPageView(eventId, 'app');
  }, [e?.id, id, userId, demo]));
  useEffect(() => {
    const groupId = e?.group_id;
    if (!groupId) { setGroup(null); return; }
    let live = true;
    getGroup(groupId).then((row) => { if (live) setGroup(row ? { id: row.id, name: row.name } : null); }).catch(() => { if (live) setGroup(null); });
    return () => { live = false; };
  }, [e?.group_id]);
  const mark = (next: boolean) => {
    if (!userId || !id || !e) return;
    if (next && attendanceClosed(e)) {
      setErr(attendanceClosedMessage(e));
      return;
    }
    setBusy(true); setErr(null);
    const run = (async () => {
      if (!next) {
        await cancelAttend(id, userId);
        return;
      }
      const visibility = eventVisibility(e.visibility);
      if (visibility === 'hidden') {
        const token = await eventUnlistedToken(id);
        if (!token) throw new Error('Use the unlisted link to RSVP.');
        await attendUnlistedEvent(token);
        return;
      }
      if (visibility === 'private' && application !== 'approved') {
        await applyToEvent(id);
        return;
      }
      await attendEvent(id, userId);
    })();
    run.then(load).catch((x) => setErr(x.message)).finally(() => setBusy(false));
  };
  const remove = (options: { unlinkMeetup: boolean }) => {
    if (!id) return;
    removeSheet.run(async () => {
      await deleteEvent(id, options);
      flash('Event deleted');
      router.replace('/events');
    });
  };

  if (loading) return (
    <Page scroll={false} fill>
      <BackChevron fallback="/events" />
      <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>
    </Page>
  );
  if (!userId) {
    const next = id ? `/events/${id}` : null;
    if (next) rememberReturnPath(next);
    return <Redirect href={next ? `/sign-in?next=${encodeURIComponent(next)}` : '/sign-in'} />;
  }

  if (e === undefined) return <Page><BackChevron fallback="/events" /><ErrorText>{err}</ErrorText></Page>;
  if (e === null) return <Page><BackChevron fallback="/events" /><EmptyState icon="calendar-outline" title="Event not found" body="It may have been removed."
    action={<Button small variant="neutral" title="All events" onPress={() => router.replace('/events')} />} /></Page>;
  const ended = eventEndMs(e) <= Date.now();
  const past = attendanceClosed(e);
  const visibility = eventVisibility(e.visibility);
  const action = rsvpAction({ visibility, past, going, application });
  const canReview = visibility === 'private' && (mod || (!!userId && e.owner_id === userId));
  const unlocked = !!e.place_unlocked;
  const where = unlocked
    ? entitledWhere(e.venue_name, e.venue_address, e.online_meeting_url)
    : lockedWhere(e.venue_name, e.venue_locality);
  const about = unlocked ? e.description : publicDescription(e.description);
  const groupLink = group
    ? <Text onPress={() => router.push(`/groups/${group.id}`)} style={styles.link}>{group.name}</Text>
    : null;
  const headerFields: [string, React.ReactNode][] = [
    ['Starts', fmtDate(e.starts_at)],
    ['Ends', fmtDate(e.ends_at)],
    ['Where', <PlaceValue place={where} />],
  ];
  if (groupLink) headerFields.push(['Group', groupLink]);
  if (owner) headerFields.push(['Owner', <OwnerFace profile={owner} />]);
  return (
    <Page>
      <Stack.Screen options={{ title: e.title, headerShown: false }} />
      <BackChevron fallback="/events" />
      <CoverBand url={e.image_url} />
      <EntityTitle title={e.title} meta={fmtDate(e.starts_at)} pills={<>
        {e.archived ? <StatusPill label="Archived" /> : <StatusPill label={ended ? 'Ended' : isLive(e) ? 'Live' : 'Upcoming'} tone={ended ? 'default' : isLive(e) ? 'success' : 'info'} />}
        {mod && visibility !== 'public' ? <StatusPill label={eventVisibilityLabel(visibility)} tone={visibility === 'hidden' ? 'warning' : 'info'} /> : null}
      </>} />
      <ActionRow>
        {going
          ? <Button small variant="neutral" title="Cancel RSVP" loading={busy} onPress={() => mark(false)} />
          : action === 'apply'
            ? <Button small icon="checkmark-outline" title={application === 'declined' ? 'Apply again' : 'Apply'} loading={busy} onPress={() => mark(true)} />
            : action === 'pending'
              ? <Button small variant="neutral" title="Application pending" disabled />
              : action === 'attend'
                ? <Button small icon="checkmark-outline" title={visibility === 'hidden' ? 'RSVP' : 'Attend'} loading={busy} onPress={() => mark(true)} />
                : null}
        {mod ? <Button small variant="neutral" icon="create-outline" title="Edit" onPress={() => router.push(`/events/manage/${e.id}`)} /> : null}
        {mod ? <Button small variant="neutral" icon="bar-chart-outline" title="Analytics" onPress={() => router.push(`/events/${e.id}/analytics`)} /> : null}
        {canDelete ? <Button small variant="danger" icon="trash-outline" title="Delete" onPress={removeSheet.ask} /> : null}
      </ActionRow>
      <FieldGrid fields={headerFields} />
      <ErrorText>{err}</ErrorText>
      {mod ? <PublishToList event={e} /> : null}
      {canReview ? <EventApplications eventId={e.id} /> : null}
      <SectionCard title="Details">
        {unlocked ? (
            <FieldGrid fields={[
            ['Starts', fmtDate(e.starts_at)],
            ['Ends', fmtDate(e.ends_at)],
            ['Venue', e.venue_name ?? '—'],
            ['Address', <PlaceValue place={entitledAddress(e.venue_address, e.online_meeting_url)} />],
            ...(groupLink ? [['Group', groupLink] as [string, React.ReactNode]] : []),
          ]} />
        ) : (
          <>
            <FieldGrid fields={[
              ...lockedDetailFields(fmtDate(e.starts_at), fmtDate(e.ends_at), e.venue_name, e.venue_locality),
              ...(groupLink ? [['Group', groupLink] as [string, React.ReactNode]] : []),
            ]} />
            <Text style={[styles.muted, { marginTop: 12 }]}>{past
              ? attendanceClosedMessage(e)
              : visibility === 'private' && !going
                ? 'Apply to see the exact place. The host approves requests. Names stay off the public page.'
                : visibility === 'hidden' && !going
                  ? 'RSVP with your account to see the exact place. Plus-ones aren’t available.'
                  : 'Attend to see the exact place and the online join link.'}</Text>
          </>
        )}
      </SectionCard>
      <EventSeries eventId={e.id} fallbackTitle={e.title} />
      <EventChats eventId={e.id} eventTitle={e.title} />
      {about ? <SectionCard title="About"><RichText source={about} /></SectionCard> : null}
      {mod && e.meetup_id ? <EventAttendance meetupEventId={e.meetup_id} /> : null}
      <DeleteEventSheet visible={removeSheet.open} meetupLinked={!!e.meetup_id} busy={removeSheet.busy} error={removeSheet.error}
        onCancel={removeSheet.cancel}
        onConfirm={remove} />
    </Page>
  );
}
