// Chats linked to a club event. Hosts see the section even when it is empty.
// A chat row is only rendered for someone who was included in that chat.
import React, { useCallback, useState } from 'react';
import { Pressable, Text, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router, useFocusEffect } from 'expo-router';
import { Button, EmptyState, ErrorText, SectionCard, styles } from './ui';
import { EventChatSheet } from './event-chat-sheet';
import { canLinkEventChat, listEventChats } from '../lib/api';
import { eventChatRowSubtitle, type EventChatSummary } from '../lib/event-chats';
import { flash } from '../lib/flash';
import { useSession } from '../lib/session';
import { colors, fs } from '../lib/theme';

export function EventChats({ eventId, eventTitle }: { eventId: string; eventTitle: string }) {
  const { userId } = useSession();
  const [host, setHost] = useState(false);
  const [chats, setChats] = useState<EventChatSummary[] | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<EventChatSummary | null>(null);

  const load = useCallback(() => {
    if (!userId || !eventId) return;
    Promise.all([canLinkEventChat(eventId), listEventChats(eventId)]).then(([canLink, rows]) => {
      setHost(canLink);
      setChats(rows);
      setErr(null);
      setLoaded(true);
    }).catch((e: { message?: string }) => {
      setErr(e.message ?? 'Couldn’t load chats.');
      setLoaded(true);
    });
  }, [userId, eventId]);

  useFocusEffect(useCallback(() => { load(); }, [load]));

  if (!loaded) return null;
  const rows = chats ?? [];
  if (chats === null && !host && !err) return null;
  if (!host && rows.length === 0 && !err) return null;

  return (
    <View testID="event-chats">
      <SectionCard title="Chats" padded={false} actions={host ? (
        <Button small icon="chatbubble-outline" title="New chat" onPress={() => setCreating(true)} />
      ) : null}>
        <ErrorText>{err}</ErrorText>
        {rows.length === 0 ? (
          <EmptyState compact icon="chatbubbles-outline" title="No chats yet"
            body={host ? 'Start one and choose who to include. People who can see this event aren’t added.' : undefined} />
        ) : rows.map((chat) => {
          const mine = !!userId && chat.created_by === userId;
          return (
            <View key={chat.room_id} style={styles.row}>
              <Pressable accessibilityRole="link" accessibilityLabel={`Open ${chat.title}`}
                onPress={() => router.push(`/rooms/${chat.room_id}`)} style={{ flex: 1, minWidth: 0 }}>
                <Text style={styles.rowPrimary} numberOfLines={1}>{chat.title}</Text>
                <Text style={[styles.muted, { fontSize: fs(12), marginTop: 2 }]} numberOfLines={1}>
                  {eventChatRowSubtitle(chat.member_count, chat.event_count)}
                </Text>
              </Pressable>
              {mine && host ? (
                <Pressable accessibilityRole="button" accessibilityLabel={`Edit events for ${chat.title}`}
                  onPress={() => setEditing(chat)} hitSlop={8} style={{ paddingVertical: 4, paddingHorizontal: 6 }}>
                  <Text style={styles.link}>Links</Text>
                </Pressable>
              ) : null}
              <Ionicons name="chevron-forward" size={16} color={colors.faint} />
            </View>
          );
        })}
      </SectionCard>
      <EventChatSheet visible={creating} mode="create" anchorId={eventId} anchorTitle={eventTitle}
        onClose={() => setCreating(false)}
        onSaved={(id) => {
          setCreating(false);
          load();
          flash('Chat created');
          router.push(`/rooms/${id}`);
        }} />
      <EventChatSheet visible={!!editing} mode="edit" anchorId={eventId} anchorTitle={eventTitle} roomId={editing?.room_id}
        onClose={() => setEditing(null)}
        onSaved={() => { setEditing(null); load(); }} />
    </View>
  );
}
